from common76 import *
import collections

def choose(rr,n,salt):
 # Round-robin recordings then camera suffixes, fixed hash, no task/visibility filter.
 by=collections.defaultdict(list)
 for r in rr:by[r['scene']].append(r)
 for sc in by:by[sc].sort(key=lambda r:hashlib.sha256((salt+'|'+str(r['suffix'])+'|'+r['id']).encode()).hexdigest())
 order=sorted(by,key=lambda s:hashlib.sha256((salt+'scene|'+s).encode()).hexdigest());out=[]
 while len(out)<n:
  for sc in order:
   if by[sc]:out.append(by[sc].pop(0))
   if len(out)==n:break
 return out
